<?php
declare(strict_types=1);
namespace Nexus\Features\Administracion\Application;
use Nexus\Features\Administracion\Domain\AdministracionRepository;use Nexus\Shared\Domain\ValueObject\Cedula;use Nexus\Shared\DomainException;
final class AdministracionService
{
    private AdministracionRepository $repo;private const CATALOGOS=['categoria_tecnologica','categoria_prestamo','servicio_disponible'];
    public function __construct(AdministracionRepository $r){$this->repo=$r;}
    public function reportes():array{return $this->repo->listarReportes();}public function crearReporte(array $d):int{foreach(['tipo','contacto','asunto','detalle'] as $k)if($d[$k]==='')throw new DomainException('Completa todos los datos del reporte.');return $this->repo->crearReporte($d);}public function actualizarReporte(int $id,string $estado,string $respuesta,Cedula $r):void{if(!in_array($estado,['Pendiente','En proceso','Resuelto','Rechazado'],true))throw new DomainException('Estado no válido.');if(!$this->repo->actualizarReporte($id,['estado'=>$estado,'respuesta'=>$respuesta],$r))throw new DomainException('No existe el reporte o no hubo cambios.',404);}
    public function catalogo(string $t,bool $i):array{$this->exigirCatalogo($t);return $this->repo->listarCatalogo($t,$i);}public function crearCatalogo(string $t,string $n,string $d):int{$this->exigirCatalogo($t);if($n==='')throw new DomainException('El nombre es obligatorio.');return $this->repo->crearCatalogo($t,$n,$d);}public function editarCatalogo(string $t,int $id,string $n,string $d,bool $a):void{$this->exigirCatalogo($t);if($n==='')throw new DomainException('El nombre es obligatorio.');if(!$this->repo->editarCatalogo($t,$id,['nombre'=>$n,'descripcion'=>$d,'activo'=>$a]))throw new DomainException('No existe el registro indicado o no hubo cambios.',404);}public function bajaCatalogo(string $t,int $id):void{$this->exigirCatalogo($t);if(!$this->repo->bajaCatalogo($t,$id))throw new DomainException('No existe el registro activo indicado.',404);}
    public function configuracion():array{$r=[];foreach($this->repo->configuracion() as $f)$r[$f['clave']]=$f;return $r;}public function guardarConfiguracion(string $c,string $v,Cedula $u):void{if(!in_array($c,['dias_maximos_prestamo','registro_habilitado'],true))throw new DomainException('Configuración no permitida.');if($c==='dias_maximos_prestamo'&&(!ctype_digit($v)||(int)$v<1||(int)$v>365))throw new DomainException('Los días deben estar entre 1 y 365.');if($c==='registro_habilitado'&&!in_array($v,['0','1'],true))throw new DomainException('Valor de registro no válido.');$this->repo->guardarConfiguracion($c,$v,$u);}
    public function historial():array{return array_map(function($f){$fecha=new \DateTimeImmutable($f['fecha_registrado']);$cedula=trim((string)($f['autor_cedula']??''));$nombre=trim((string)($f['autor_nombre']??''));$autor=$nombre!==''?$nombre:($cedula!==''?'Usuario':'Sistema');return ['id'=>$f['tipo'].'-'.$f['id'],'color'=>'azul','titulo'=>$f['etiqueta'].': '.$f['referencia'],'etiqueta'=>$f['etiqueta'],'colorEtiqueta'=>'info','descripcion'=>$f['descripcion']?:'','autor'=>$autor,'autorId'=>$cedula!==''?$cedula:'sistema','fecha'=>$fecha->format('d/m/Y'),'hora'=>$fecha->format('H:i'),'tipo'=>$f['tipo']];},$this->repo->historial());}
    private function exigirCatalogo(string $t):void{if(!in_array($t,self::CATALOGOS,true))throw new DomainException('Catálogo no válido.');}
}
